import {depotEase} from './depot-motion.js?v=depot-v12';
import {recordSceneAsset} from './scene-geometry.js?v=depot-v12';
export function finaleState(t,f){const q=depotEase((t-f.depotFrameStart)/Math.max(.1,f.depotFrameTime)),crack=depotEase((t-f.depotCrackStart)/Math.max(.1,f.depotCrackTime)),tilt=depotEase((t-f.depotTiltStart)/Math.max(.1,f.depotTiltTime));return {q,crack,tilt,scale:1.13+(f.depotFrameEndScale-1.13)*q,angle:f.depotFrameRotation*tilt*Math.PI/180,skew:-Math.sin(f.depotFrameTilt*tilt*Math.PI/180)*.25,mono:q,brightness:1-(f.depotFrameDarkness??.78)*q}}
// Continuous fractal density, available immediately even before image decoding.
export function cloudDensity(x,y,seed=1){const hash=(a,b)=>{const v=Math.sin(a*127.1+b*311.7+seed*43.7)*43758.5453;return v-Math.floor(v)},noise=(x,y)=>{const a=Math.floor(x),b=Math.floor(y);let u=x-a,v=y-b;u=u*u*(3-2*u);v=v*v*(3-2*v);return (hash(a,b)*(1-u)+hash(a+1,b)*u)*(1-v)+(hash(a,b+1)*(1-u)+hash(a+1,b+1)*u)*v};let n=0,amp=.54;for(let k=0;k<6;k++){n+=noise(x,y)*amp;x=x*2.03+7;y=y*2.01+3;amp*=.48}return n}
export function createDepotFinale(){const cache=new Map(),cloud=new Image();cloud.src='assets/clouds.png';function sprite(color){if(!cloud.naturalWidth)return null;const key='sprite:'+color;if(cache.has(key))return cache.get(key);const b=document.createElement('canvas');b.width=cloud.naturalWidth;b.height=cloud.naturalHeight;const g=b.getContext('2d');g.drawImage(cloud,0,0);g.globalCompositeOperation='multiply';g.fillStyle=color;g.fillRect(0,0,b.width,b.height);g.globalCompositeOperation='destination-in';g.drawImage(cloud,0,0);cache.set(key,b);return b}function texture(color,seed){const key=color+seed;if(cache.has(key))return cache.get(key);const b=document.createElement('canvas');b.width=b.height=320;const g=b.getContext('2d'),im=g.createImageData(320,320),rgb=[1,3,5].map(i=>parseInt(color.slice(i,i+2),16));for(let y=0;y<320;y++)for(let x=0;x<320;x++){const n=cloudDensity(x/72,y/72,seed),edge=cloudDensity(x/72-.035,y/72-.04,seed),mass=Math.max(0,Math.min(1,(n-.25)*2.1)),light=Math.max(.025,Math.min(1.5,.08+mass*.9+(n-edge)*10)),i=(y*320+x)*4;for(let k=0;k<3;k++)im.data[i+k]=Math.min(255,rgb[k]*light+mass*mass*22);im.data[i+3]=255}g.putImageData(im,0,0);if(cache.size>8)cache.clear();cache.set(key,b);return b}return {paint(c,t,f,photo){const s=finaleState(t,f);c.fillStyle='#080d14';c.fillRect(0,0,960,540);const flash=Math.pow(Math.max(0,Math.sin(t*f.depotLightningRate*6.28)),55);for(const [color,x,seed]of [[f.depotCloudLeft,0,112],[f.depotCloudRight,480,113]]){c.save();c.beginPath();c.rect(x,0,480,540);c.clip();const drift=Math.sin(t*f.depotStormSpeed/250+seed)*45,vertical=Math.cos(t*f.depotStormSpeed/340+seed)*25+(f.depotCloudY-120);const billows=sprite(color);c.globalAlpha=.25*Math.min(1,(f.depotStormDensity??100)/100);if(!billows)c.drawImage(texture(color,seed),x-130+drift,-130+vertical,760,820);else{const shade=c.createLinearGradient(x,0,x+480,540);shade.addColorStop(0,'#050a12');shade.addColorStop(.6,color+'77');shade.addColorStop(1,'#050810');c.fillStyle=shade;c.fillRect(x,0,480,540)}if(billows){c.globalAlpha=.68*Math.min(1,(f.depotStormDensity??100)/100);for(let j=0;j<3;j++){c.save();c.translate(x+240+drift*(j%2?1:-1),j*235-120+vertical);c.rotate(j%2?.18:-.2);c.drawImage(billows,-600,-60,1200,490);c.restore()}}c.globalAlpha=1;if(flash>.01){c.globalCompositeOperation='screen';c.globalAlpha=flash*.55*f.depotLightningBrightness;const glow=c.createRadialGradient(x+260,250,0,x+260,250,320);glow.addColorStop(0,'#fff1cf');glow.addColorStop(1,'#fff1cf00');c.fillStyle=glow;c.fillRect(x,0,480,540)}c.restore();recordSceneAsset(c,{id:'depot-storm-'+seed,kind:'depotStorm',name:seed===112?'Left storm clouds':'Right storm clouds'},[x,0,480,540])}

function bolt(x,seed,opacity,width){c.save();c.globalCompositeOperation='screen';c.globalAlpha=opacity*f.depotLightningBrightness;c.strokeStyle='#fff6ef';c.shadowColor='#fff';c.shadowBlur=24;c.lineWidth=width;c.beginPath();for(let i=0;i<=58;i++){const px=x+Math.sin(i*2.7+seed)*5+Math.sin(i*.6+seed)*22,py=i*540/58;i?c.lineTo(px,py):c.moveTo(px,py)}c.stroke();c.restore()}
bolt(f.depotDividerX,2,.7+Math.pow(Math.max(0,Math.sin(t*1.7)),18)*.3,f.depotDividerWidth);const pulse=Math.pow(Math.max(0,Math.sin(t*f.depotLightningRate*6.28)),55);if(pulse>.02){bolt(160,Math.floor(t*2),pulse,2);bolt(780,Math.floor(t*2)+4,pulse,2);const g=c.createRadialGradient(730,240,1,730,240,380);g.addColorStop(0,'#fff6');g.addColorStop(1,'#fff0');c.fillStyle=g;c.globalAlpha=pulse;c.fillRect(0,0,960,540);c.globalAlpha=1}
recordSceneAsset(c,{id:'depot-lightning',kind:'depotLightning',name:'Storm lightning and glowing divide'},[f.depotDividerX-22,0,44,540]);c.save();c.translate(480,270);c.rotate(s.angle);c.transform(1,s.skew,0,Math.max(.25,Math.cos(f.depotFrameTilt*s.tilt*Math.PI/180)),0,0);c.scale(s.scale,s.scale);c.shadowColor='#000b';c.shadowBlur=30;c.shadowOffsetY=15;const gold=c.createLinearGradient(-500,-280,500,280);for(const [p,v]of [[0,'#281305'],[.2,'#c58b33'],[.4,'#51300d'],[.55,'#e3ac4c'],[.8,'#7f4819'],[1,'#281504']])gold.addColorStop(p,v);c.fillStyle=gold;c.fillRect(-515,-305,1030,610);c.shadowBlur=0;c.shadowOffsetY=0;c.strokeStyle='#d2a044';c.lineWidth=3;for(let i=0;i<4;i++)c.strokeRect(-508+i*5,-298+i*5,1016-i*10,596-i*10);c.fillStyle='#17100a';c.fillRect(-484,-274,968,548);c.save();c.filter=`grayscale(${s.mono}) brightness(${s.brightness})`;c.drawImage(photo,-480,-270,960,540);c.restore();for(let i=0;i<80;i++){const x=-493+i*12.5;c.fillStyle=i%2?'#a86c22':'#e1ad50';for(const y of [-285,285]){c.beginPath();c.ellipse(x,y,3.5,3,0,0,7);c.fill()}}for(let i=0;i<44;i++)for(const x of [-495,495]){c.fillStyle=i%2?'#a46c24':'#d69a38';c.beginPath();c.arc(x,-268+i*12.5,3,0,7);c.fill()}
if(s.crack>0){c.save();c.beginPath();c.rect(-480,-270,960,540);c.clip();const rays=18;for(let i=0;i<rays;i++){const a=i*6.283/rays+.11*Math.sin(i*8),reach=(150+390*(.5+.5*Math.sin(i*29)))*s.crack,x=Math.cos(a)*reach,y=Math.sin(a)*reach;c.strokeStyle='#161719';c.lineWidth=(f.depotCrackStrength??.8)*(1+1*s.crack);c.beginPath();c.moveTo(-12,0);c.lineTo(x*.45+Math.sin(i)*20,y*.45);c.lineTo(x,y);c.stroke();c.strokeStyle='#d9dce699';c.lineWidth=(f.depotCrackStrength??.8)*.45;c.stroke();if(s.crack>.5){c.beginPath();c.moveTo(x*.55,y*.55);c.lineTo(x*.6+45,y*.6-35);c.lineTo(x*.8+65,y*.8-20);c.stroke()}}c.restore()}
recordSceneAsset(c,{id:'depot-frame',kind:'depotFrame',name:'Cracking gold picture frame'},[-515,-305,1030,610]);c.restore();return s}}}
